export default{
  props:['scene'],
  data:()=>({field:null,compareField:null,probePoint:null,selectedCritical:null,trajectories:[],criticalPoints:null,drawnPath:[],pathResult:null,drawing:false,automaticLines:null,basinResult:null,licSurface:null,dashPhase:0,options:{grid:true,axes:true,arrows:true,heatmap:false,contours:false,critical:true,lic:false,nullclines:false,isoclines:false,separatrices:false,integralLens:false,pathIntegral:false,basins:false,autoStreamlines:false,arrowDensity:22,arrowScale:'sqrt',opacity:.82,palette:'magnitude',heatmapPalette:'viridis',matchParticles:false,rangeMode:'percentile',rangeMin:0,rangeMax:1,contourQuantity:'magnitude',contourLevels:9,linkContourDensity:true,contourSmoothing:1,contourLabels:true,contourFill:false,adaptiveContours:true,sampleQuality:'balanced',probe:true,trajectories:true,animateStreamlines:false,compareMode:'overlay',particlePalette:'cyan',particleColor:'#4ec4ff'},timer:0}),
  mounted(){this.ctx=this.$refs.canvas.getContext('2d',{alpha:true});this.redraw=this.redraw.bind(this);this.onField=m=>{this.field=m;this.trajectories=[];this.criticalPoints=null;this.selectedCritical=null;this.automaticLines=null;this.basinResult=null;this.licSurface=null;this.stopAnimation();this.schedule();};this.onCompare=m=>{this.compareField=m;this.schedule();};this.onOptions=o=>{if(o.arrowDensity!==undefined||o.autoStreamlines!==undefined)this.automaticLines=null;Object.assign(this.options,o);this.options.animateStreamlines?this.startAnimation():this.stopAnimation();this.schedule();};this.onBounds=()=>{this.criticalPoints=null;this.automaticLines=null;this.basinResult=null;this.licSurface=null;this.schedule();};this.onMove=e=>{if(!(this.options.probe||this.options.integralLens)||isControl(e.target)||this.drawing){this.probePoint=null;return;}this.probePoint=this.eventPoint(e);this.schedule(16);};this.onPointerDown=e=>{if(!this.options.pathIntegral||isControl(e.target)||e.button!==0)return;const p=this.eventPoint(e);if(!p||!this.field)return;e.preventDefault();e.stopPropagation();this.drawing=true;this.drawnPath=[[p.x,p.y]];this.pathResult=null;this.schedule(0);};this.onPointerDrag=e=>{if(!this.drawing)return;const p=this.eventPoint(e);if(!p)return;e.preventDefault();e.stopPropagation();const last=this.drawnPath.at(-1),b=this.scene.getBoundingBox(),span=b.maxX-b.minX;if(!last||Math.hypot(p.x-last[0],p.y-last[1])>span/500)this.drawnPath.push([p.x,p.y]);this.schedule(0);};this.onPointerUp=e=>{if(!this.drawing)return;e.preventDefault();e.stopPropagation();this.drawing=false;if(this.drawnPath.length>1)this.pathResult=polylineIntegrals(this.field,this.drawnPath,{closed:e.shiftKey});this.schedule(0);};this.onClick=e=>{if(isControl(e.target)||this.options.pathIntegral||this.drawing)return;const p=this.eventPoint(e);if(!p||!this.field)return;const b=this.scene.getBoundingBox(),near=this.criticalPoints?.find(q=>Math.hypot(q.x-p.x,q.y-p.y)<(b.maxX-b.minX)/45);if(near){