    drawArrows(b,rect,field,fixedColor){const ctx=this.ctx,n=Math.max(8,Math.min(42,this.options.arrowDensity)),{samples,maxLen}=getArrowSamples(field,b,rect,n),range=colorRange(samples.map(s=>s.m),this.options),vmax=range[1],transform=createViewportTransform(b,rect),paletteName=this.options.matchParticles?this.options.particlePalette:this.options.palette;ctx.save();ctx.lineCap='round';for(const s of samples){if(s.m<1e-10)continue;const raw=scaledValue(s.m,range,this.options.rangeMode),t=scaleMagnitude(raw,this.options.arrowScale),len=maxLen*(this.options.arrowScale==='normalized'?1:.25+.75*t),arrow=arrowSegment(transform,s.x,s.y,s.v[0],s.v[1],len);if(!arrow)continue;const color=fixedColor||arrowColor(paletteName,raw,s.v,this.options.opacity,this.options.particleColor);drawArrow(ctx,arrow,len,'rgba(1,8,18,.8)',3.4);drawArrow(ctx,arrow,len,color,1.45);}ctx.restore();if(!fixedColor&&paletteName==='magnitude')this.drawLegend(rect,vmax,paletteName,'|F|');},
    drawHeatmap(grid,rect){const ctx=this.ctx,values=grid.magnitude,range=colorRange(values,this.options),cw=rect.width/grid.cols,ch=rect.height/grid.rows;ctx.save();for(let j=0;j<grid.rows;j++)for(let i=0;i<grid.cols;i++){const k=j*(grid.cols+1)+i,t=scaledValue(values[k],range,this.options.rangeMode);ctx.fillStyle=paletteColor(this.options.heatmapPalette,t,.28);ctx.fillRect(rect.left+i*cw,rect.top+j*ch,cw+1,ch+1);}ctx.restore();this.drawLegend(rect,range[1],this.options.heatmapPalette,'|F|');},
    drawLIC(grid,rect){const w=grid.cols+1,h=grid.rows+1,key=`${w}|${h}|${this.options.sampleQuality}`;if(this.licSurface?.key!==key||this.licSurface?.grid!==grid){const values=lineIntegralConvolution(grid,this.options.sampleQuality==='detail'?16:10),canvas=typeof OffscreenCanvas==='function'?new OffscreenCanvas(w,h):document.createElement('canvas');canvas.width=w;canvas.height=h;const c=canvas.getContext('2d'),image=c.createImageData(w,h);for(let i=0;i<values.length;i++){const v=Math.round(255*Math.max(0,Math.min(1,values[i]))),k=i*4;image.data[k]=v;image.data[k+1]=Math.min(255,v+28);image.data[k+2]=Math.min(255,v+55);image.data[k+3]=105;}c.putImageData(image,0,0);this.licSurface={key,grid,canvas};}this.ctx.save();this.ctx.imageSmoothingEnabled=true;this.ctx.drawImage(this.licSurface.canvas,rect.left,rect.top,rect.width,rect.height);this.ctx.restore();},
