    drawAutomaticStreamlines(b,map){const key=`${b.minX}|${b.maxX}|${b.minY}|${b.maxY}|${this.options.arrowDensity}`;if(this.automaticLines?.key!==key)this.automaticLines={key,lines:placeStreamlines(this.field,b,{density:Math.max(10,Math.round(this.options.arrowDensity*.72)),maxLines:Math.max(20,Math.round(this.options.arrowDensity*1.7))})};const ctx=this.ctx,color=paletteColor(this.options.matchParticles?this.options.particlePalette:this.options.palette,.68,.66);ctx.save();ctx.lineCap='round';ctx.lineJoin='round';for(const line of this.automaticLines.lines){const points=line.map(p=>map(p[0],p[1]));strokePath(ctx,points,'rgba(1,8,18,.72)',3.4);strokePath(ctx,points,color,1.15);}ctx.restore();},
    drawIntegralPath(map){const points=this.drawnPath.map(p=>map(p[0],p[1]));if(this.pathResult?.closed&&points.length>2)points.push(points[0]);const ctx=this.ctx;ctx.save();ctx.lineJoin='round';ctx.lineCap='round';strokePath(ctx,points,'rgba(1,8,18,.94)',6);strokePath(ctx,points,'#ffe154',2.5);for(const p of[points[0],points.at(-1)]){if(!p)continue;ctx.fillStyle='#ffe154';ctx.beginPath();ctx.arc(p[0],p[1],4,0,Math.PI*2);ctx.fill();}if(this.pathResult){const text=`Flux ${fmt(this.pathResult.flux)}   Circulation ${fmt(this.pathResult.circulation)}   Length ${fmt(this.pathResult.length)}${this.pathResult.closed?'   closed':''}`,anchor=points.at(-1),tw=ctx.measureText(text).width+14,bx=Math.max(8,Math.min(innerWidth-tw-8,anchor[0]+10)),by=Math.max(8,Math.min(innerHeight-28,anchor[1]-28));ctx.font='11px ui-monospace,monospace';ctx.fillStyle='rgba(2,8,18,.95)';ctx.fillRect(bx,by,tw,20);ctx.fillStyle='#ffe154';ctx.fillText(text,bx+7,by+14);}ctx.restore();},
    drawNullclines(grid,rect){const ctx=this.ctx;ctx.save();ctx.translate(rect.left,rect.top);for(const [values,color,label] of[[grid.fx,'#57c7ff','dx/dt = 0'],[grid.fy,'#ff6faf','dy/dt = 0']]){const paths=extractContourPaths(values,grid.cols,grid.rows,0,rect.width,rect.height);for(const path of paths)strokePath(ctx,smoothContourPath(path,1),'rgba(1,8,18,.9)',4),strokePath(ctx,smoothContourPath(path,1),color,2);if(paths[0]?.length){const p=paths[0][Math.floor(paths[0].length/2)];ctx.fillStyle=color;ctx.font='11px ui-monospace,monospace';ctx.fillText(label,p[0]+5,p[1]-5);}}ctx.restore();},
    drawIsoclines(grid,rect){const ctx=this.ctx,w=grid.cols+1,size=w*(grid.rows+1);ctx.save();ctx.translate(rect.left,rect.top);for(let n=0;n<4;n++){const angle=n*Math.PI/4,values=new Float32Array(size);for(let k=0;k<size;k++)values[k]=Math.sin(Math.atan2(grid.fy[k],grid.fx[k])-angle);const color=paletteColor('twilight',n/4,.62);for(const path of extractContourPaths(values,grid.cols,grid.rows,0,rect.width,rect.height))strokePath(ctx,smoothContourPath(path,1),color,1.1);}ctx.restore();},
