    drawSeparatrices(b,map){if(!this.criticalPoints)this.criticalPoints=findCriticalPoints(this.field.evaluate,b,{grid:24});const ctx=this.ctx,span=Math.min(b.maxX-b.minX,b.maxY-b.minY);ctx.save();for(const p of this.criticalPoints.filter(x=>x.classification==='saddle')){for(const vector of saddleEigenvectors(p.jacobian)){for(const sign of[-1,1]){const start={x:p.x+vector[0]*span*.002*sign,y:p.y+vector[1]*span*.002*sign},points=traceStreamline(this.field,start,b,{direction:sign,tolerance:5e-5}).map(q=>map(q[0],q[1]));strokePath(ctx,points,'rgba(1,8,18,.9)',5);strokePath(ctx,points,'rgba(255,190,84,.92)',2.2);}}}ctx.restore();},
    drawIntegralLens(b,map){const p=this.probePoint,r=Math.min(b.maxX-b.minX,b.maxY-b.minY)*.08,result=circleIntegrals(this.field,p.x,p.y,r),[cx,cy]=map(p.x,p.y),[edge]=map(p.x+r,p.y),rp=Math.abs(edge-cx),ctx=this.ctx;ctx.save();ctx.strokeStyle='#ffe154';ctx.lineWidth=2;ctx.setLineDash([6,4]);ctx.beginPath();ctx.arc(cx,cy,rp,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);const text=`Flux ${fmt(result.flux)}   Circulation ${fmt(result.circulation)}`;ctx.font='11px ui-monospace,monospace';const tw=ctx.measureText(text).width+14,bx=Math.min(innerWidth-tw-8,cx-rp),by=Math.max(8,cy-rp-25);ctx.fillStyle='rgba(2,8,18,.94)';ctx.fillRect(bx,by,tw,20);ctx.fillStyle='#ffe154';ctx.fillText(text,bx+7,by+14);ctx.restore();},
    drawDifferentialGlyph(b,map){const p=this.probePoint,q=analyzePoint(this.field.evaluate,p.x,p.y,(b.maxX-b.minX)*1e-5),[x,y]=map(p.x,p.y),ctx=this.ctx,r=15;ctx.save();ctx.translate(x,y);ctx.strokeStyle=q.divergence>=0?'#74d680':'#ff6f8f';ctx.lineWidth=1.6;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.stroke();const sign=q.divergence>=0?1:-1;for(let a=0;a<Math.PI*2;a+=Math.PI/2){ctx.beginPath();ctx.moveTo(Math.cos(a)*r*.35,Math.sin(a)*r*.35);ctx.lineTo(Math.cos(a)*r*(.55+.35*sign),Math.sin(a)*r*(.55+.35*sign));ctx.stroke();}ctx.strokeStyle='#ffd65d';ctx.beginPath();const turn=q.curl>=0?1:-1;ctx.arc(0,0,r+5,turn>0?-.3:Math.PI+.3,turn>0?Math.PI*1.25:Math.PI*.75,turn<0);ctx.stroke();ctx.restore();},
    drawProbe(b,map){const p=this.probePoint,q=analyzePoint(this.field.evaluate,p.x,p.y,(b.maxX-b.minX)*1e-5),v=q.vector,m=Math.hypot(...v),eig=eigenvalues(q.jacobian),[x,y]=map(p.x,p.y),ctx=this.ctx,lines=[`(${fmt(p.x)}, ${fmt(p.y)})  r=${fmt(Math.hypot(p.x,p.y))} θ=${fmt(Math.atan2(p.y,p.x))}`,`F=(${fmt(v[0])}, ${fmt(v[1])})  |F|=${fmt(m)}`,`div=${fmt(q.divergence)}  curl=${fmt(q.curl)}  det J=${fmt(q.determinant)}`,`λ₁=${eig[0]}  λ₂=${eig[1]}`];ctx.save();ctx.fillStyle='#fff';ctx.strokeStyle='#07111f';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.stroke();ctx.fill();const boxX=Math.min(innerWidth-330,x+12),boxY=Math.max(8,y-82);ctx.fillStyle='rgba(2,8,18,.94)';ctx.strokeStyle='#365875';ctx.lineWidth=1;ctx.fillRect(boxX,boxY,318,73);ctx.strokeRect(boxX,boxY,318,73);ctx.font='11px ui-monospace,monospace';lines.forEach((line,i)=>{ctx.fillStyle=i?'#9ec8ed':'#fff';ctx.fillText(line,boxX+8,boxY+15+i*16);});ctx.restore();},
    drawCriticalCard(p,map){const[x,y]=map(p.x,p.y),ctx=this.ctx,eig=eigenvalues(p.jacobian),lines=[`${p.classification} at (${fmt(p.x)}, ${fmt(p.y)})`,`J = [${p.jacobian[0].map(fmt).join(', ')}; ${p.jacobian[1].map(fmt).join(', ')}]`,`eigenvalues: ${eig.join(', ')}`];ctx.save();const bx=Math.min(innerWidth-310,x+12),by=Math.min(innerHeight-65,y+12);ctx.fillStyle='rgba(2,8,18,.95)';ctx.strokeStyle='#ffb454';ctx.fillRect(bx,by,298,58);ctx.strokeRect(bx,by,298,58);ctx.font='11px ui-monospace,monospace';lines.forEach((line,i)=>{ctx.fillStyle=i?'#b9d6ef':'#ffd38a';ctx.fillText(line,bx+8,by+15+i*16);});ctx.restore();},
    drawLegend(rect,max,name,label){const ctx=this.ctx,x=rect.left+14,y=rect.top+14,w=132,h=8,g=ctx.createLinearGradient(x,0,x+w,0);for(let i=0;i<=8;i++)g.addColorStop(i/8,paletteColor(name,i/8,1));ctx.save();ctx.fillStyle='rgba(2,8,18,.82)';ctx.fillRect(x-7,y-7,w+14,34);ctx.fillStyle=g;ctx.fillRect(x,y,w,h);ctx.fillStyle='#dcecff';ctx.font='10px system-ui';ctx.fillText(`${label} low`,x,y+21);ctx.textAlign='right';ctx.fillText(`high ${fmt(max)}`,x+w,y+21);ctx.restore();},
    drawCritical(b,map){const ctx=this.ctx;if(!this.criticalPoints)this.criticalPoints=findCriticalPoints(this.field.evaluate,b,{grid:22});this.criticalPoints.forEach(p=>{const[x,y]=map(p.x,p.y);ctx.fillStyle=p.classification==='saddle'?'#ffb454':'#ff5d8f';ctx.strokeStyle='#07111f';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,6,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#dfefff';ctx.font='11px system-ui';ctx.fillText(p.classification,x+8,y-7);});},
    exportSVG(){if(!this.field||!this.scene)return;const b=this.scene.getBoundingBox(),rect=this.scene.getCanvasRect(),svg=buildFieldSVG({field:this.field,bounds:b,width:Math.round(rect.width),height:Math.round(rect.height),options:this.options,trajectories:this.trajectories}),blob=new Blob([svg],{type:'image/svg+xml'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='fieldplay-vector.svg';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),0);}
  }
};
function strokePath(ctx,p,color,width){if(p.length<2)return;ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(p[0][0],p[0][1]);for(let i=1;i<p.length;i++)ctx.lineTo(p[i][0],p[i][1]);ctx.stroke();}
function arrowColor(name,t,v,a,custom){if(name==='rainbow'){const h=(Math.atan2(v[1],v[0])+Math.PI)/(Math.PI*2);return`hsla(${Math.round(h*360)},85%,66%,${a})`;}if(name==='custom')return hexRgba(custom,a);return paletteColor(name,t,a);}
function scaleMagnitude(t,mode){if(mode==='normalized')return 1;if(mode==='linear')return t;if(mode==='log')return Math.log1p(9*t)/Math.log(10);return Math.sqrt(t);}
function eigenvalues([[a,b],[c,d]]){const tr=a+d,disc=tr*tr-4*(a*d-b*c);if(disc>=0){const s=Math.sqrt(disc);return[fmt((tr+s)/2),fmt((tr-s)/2)];}const re=fmt(tr/2),im=fmt(Math.sqrt(-disc)/2);return[`${re}+${im}i`,`${re}-${im}i`];}
function drawArrow(ctx,a,len,color,width){ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(a.x1,a.y1);ctx.lineTo(a.x2,a.y2);ctx.stroke();const head=Math.min(6.5,len*.32);ctx.beginPath();ctx.moveTo(a.x2,a.y2);ctx.lineTo(a.x2-head*Math.cos(a.angle-.55),a.y2-head*Math.sin(a.angle-.55));ctx.lineTo(a.x2-head*Math.cos(a.angle+.55),a.y2-head*Math.sin(a.angle+.55));ctx.closePath();ctx.fill();}
function niceStep(raw){const p=10**Math.floor(Math.log10(raw)),n=raw/p;return(n<2?1:n<5?2:5)*p;}
function normalize(v,a,b){return Math.max(0,Math.min(1,(v-a)/(b-a||1)));}
function colorRange(values,options){const finite=Array.from(values).filter(Number.isFinite).sort((a,b)=>a-b);if(!finite.length)return[0,1];if(options.rangeMode==='manual'){const a=Number(options.rangeMin),b=Number(options.rangeMax);return Number.isFinite(a)&&Number.isFinite(b)&&b>a?[a,b]:[0,1];}if(options.rangeMode==='linear')return[finite[0],finite.at(-1)||1];const lo=finite[Math.floor((finite.length-1)*.02)],hi=finite[Math.floor((finite.length-1)*.98)]||1;if(options.rangeMode==='symmetric'){const m=Math.max(Math.abs(lo),Math.abs(hi));return[-m,m];}return[lo,hi>lo?hi:lo+1];}
function scaledValue(v,[lo,hi],mode){if(mode==='log'){const x=Math.max(0,v-lo),span=Math.max(1e-12,hi-lo);return Math.log1p(9*x/span)/Math.log(10);}return normalize(v,lo,hi);}
function saddleEigenvectors([[a,b],[c,d]]){const tr=a+d,det=a*d-b*c,s=Math.sqrt(Math.max(0,tr*tr-4*det)),values=[(tr+s)/2,(tr-s)/2];return values.map(l=>{let v=Math.abs(b)>Math.abs(c)?[b,l-a]:[l-d,c],m=Math.hypot(...v);if(m<1e-12){v=[1,0];m=1;}return[v[0]/m,v[1]/m];});}
function fmt(v){if(!Number.isFinite(v))return'—';const a=Math.abs(v);return a>=1000||a>0&&a<.001?v.toExponential(2):v.toFixed(a<10?3:1);}
function hexRgba(hex,a){const text=String(hex||'#4ec4ff').replace('#','');return`rgba(${parseInt(text.slice(0,2),16)},${parseInt(text.slice(2,4),16)},${parseInt(text.slice(4,6),16)},${a})`;}
function isControl(target){return target instanceof Element&&!!target.closest('.controls-container,.share');}
function getArrowSamples(field,b,rect,n){const nx=Math.max(8,Math.round(n*rect.width/rect.height)),key=`${b.minX}|${b.maxX}|${b.minY}|${b.maxY}|${rect.width}|${rect.height}|${n}|${nx}`,cached=arrowSampleCache.get(field);if(cached?.key===key)return cached;const samples=[];for(let iy=0;iy<n;iy++)for(let ix=0;ix<nx;ix++){const x=b.minX+(ix+.5)/nx*(b.maxX-b.minX),y=b.minY+(iy+.5)/n*(b.maxY-b.minY),v=field.evaluate(x,y),m=Math.hypot(...v);if(Number.isFinite(m))samples.push({x,y,v,m});}const result={key,samples,maxLen:Math.min(rect.width/nx,rect.height/n)*.72};arrowSampleCache.set(field,result);return result;}
</script>
<style>.field-overlay{position:fixed;inset:0;z-index:2;pointer-events:none}</style>
